// ----------------------------------------------------------
// Shadertoy-like メタボールおしゃれ版 + カメラ運動
//   by ChatGPT
// ----------------------------------------------------------
//
// Shadertoy では iTime, iMouse, iResolution が自動で提供される。
// mainImage 関数はピクセルごとに最終的なフラグメントカラーを出力する。

// ----------------------
// ヘルパー関数群
// ----------------------

// 擬似乱数 0.0 ~ 1.0
float getRandomValue(float seed, float index)
{
    return fract(sin(seed + index * 1234.567) * 9876.543);
}

// メタボール計算用
float calcMetaball(float r, vec2 fragVec)
{
    return r / dot(fragVec, fragVec);
}

// 回転行列を返す関数
mat2 rot2(float a)
{
    float c = cos(a);
    float s = sin(a);
    return mat2(c, -s, s, c);
}

// ----------------------
// メイン描画関数
// ----------------------
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // 画面サイズやフラグ座標（fragCoord）を使って、中心を(0,0)にした座標系
    vec2 resolution = iResolution.xy;
    vec2 uv = (fragCoord - 0.5 * resolution) / resolution.y;

    // 時間
    float t = iTime;

    // ------------------------------------------------------
    // 1. カメラ運動 : 回転 + ズーム + パン（平行移動）
    // ------------------------------------------------------
    // 1) 回転
    float camAngle = 0.2 * t;
    uv = rot2(camAngle) * uv;

    // 2) ズーム in/out（sin波でややゆったりスケール）
    float camZoom = 1.0 + 0.3 * sin(t * 0.5);
    uv *= camZoom;

    // 3) パン (x,y方向に揺らす)
    uv += 0.9 * vec2(sin(t * 0.2), cos(t * 0.2));

    // ------------------------------------------------------
    // 2. 背景の演出：時間で色を変化させるグラデーション
    // ------------------------------------------------------
    float baseHue = 0.5 + 0.5 * sin(t * 0.1);  // 0.0~1.0 をゆっくり往復
    vec3 bgColorA = vec3(0.1, 0.2, 0.4);      // やや青
    vec3 bgColorB = vec3(0.1, 0.05, 0.2);     // やや紫
    vec3 bgColor  = mix(bgColorA, bgColorB, baseHue);

    // uv.yが上ほど明るく、下ほど暗くなる簡単な縦グラデーション
    float grad = smoothstep(-0.5, 0.5, uv.y);
    bgColor = mix(bgColor * 0.5, bgColor, grad);

    // 背景色としてベースを塗る
    vec3 color = bgColor;

    // ------------------------------------------------------
    // 3. メタボール設定
    // ------------------------------------------------------
    // パーティクル数
    const int numParticles = 5;

    // 最大の広がり
    float maxRadius = 3.5;

    // パーティクル半径のばらつき
    float radiusFactorMin = 0.3;
    float radiusFactorMax = 1.2;

    // 全体に脈動感を与える（メタボールが呼吸するように拡大縮小）
    float globalScale = 1.0 + 0.2 * sin(t * 0.8);

    // 累積のメタボール影響
    float sumMetaball = 0.0;

    // パーティクルを回す速度
    float swirlSpeed = 0.7;

    // 色を段階的に混ぜるため
    vec3 accumColor = vec3(0.0);

    // ------------------------------------------------------
    // 4. パーティクル配置＋メタボール計算
    // ------------------------------------------------------
    for(int i = 0; i < numParticles; i++)
    {
        // --- 角度をランダムに決める + 時間で回転 ---
        float rndAngle = 2.0 * 3.14159 * getRandomValue(42.123, float(i));
        float swirl    = t * swirlSpeed; // 全体を回す
        float angle    = rndAngle + swirl;

        // --- 円の半径のランダム ---
        float rndRadius = getRandomValue(123.456, float(i));
        float baseDist  = maxRadius * rndRadius;

        // --- パーティクルごとに脈動させる ---
        float pulse = 0.4 * sin(t * 1.8 + float(i)) + 0.6;
        float dist  = baseDist * pulse;

        // --- パーティクルの 2D 位置 (globalScaleでスケール) ---
        vec2 pos = globalScale * dist * vec2(cos(angle), sin(angle));

        // --- パーティクルごとのメタボール半径 ---
        float r = mix(radiusFactorMin, radiusFactorMax, rndRadius);

        // --- フェードアウト(外周ほど弱く) ---
        float fade = 1.0 - (baseDist / maxRadius);

        // --- フラグメント座標との距離 ---
        vec2 fragVec = uv - pos;

        // --- メタボール強度 ---
        float mbVal = calcMetaball(r, fragVec) * fade;
        sumMetaball += mbVal;

        // --- パーティクルの色 ---
        float hueShift = 0.5 + 0.5 * sin(t * 0.4 + float(i));
        vec3 particleColorA = vec3(0.9, 0.6, 0.4); // オレンジ系
        vec3 particleColorB = vec3(0.6, 0.9, 0.8); // 水色系
        vec3 pColor = mix(particleColorA, particleColorB, hueShift);

        // --- パーティクルごとの影響色を積算 ---
        accumColor = mix(accumColor, pColor, mbVal / sumMetaball);
    }

    // パーティクル寄与度を平均
    sumMetaball /= float(numParticles);

    // メタボール色を正規化 + 強度スケール
    accumColor = normalize(accumColor) * sumMetaball;

    // sumMetaball の上限
    sumMetaball = clamp(sumMetaball, 0.0, 0.35);

    // smoothstep で縁をソフトに
    float edge = smoothstep(0.0, 0.4, sumMetaball);

    // メタボールを背景色に混ぜる
    color = mix(color, accumColor, edge);

    // 最終的な色を出力
    fragColor = vec4(color, 1.0);
}
